import React, { useEffect, useState } from 'react';
import { useForm, Controller } from 'react-hook-form';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    MenuItem,
    Autocomplete
} from '@mui/material';
import { IItem } from '../../Context/ItemContext';
import callApi from '../../Services/callApi';
import Swal from 'sweetalert2';
import { IDisease, ISymptom, useNurseForm } from '../../Context/NurseFormContext';

const units = ['mg', 'ml', 'tablet', 'capsule'];

interface FormData {
    disease_group: string;
    disease_group_name: string;
    symptom: ISymptom[]
    symptom_other?: string
}

interface Props {
    open: boolean;
    onClose: () => void;
    onOpen: () => void;
}

interface IOption {
    code: string
    label: string
}

const DiseaseModal: React.FC<Props> = ({ open, onClose, onOpen }) => {
    const { medicine, setMedicine, diseaseList, setDiseaseList } = useNurseForm();
    const { register, control, handleSubmit, reset, getValues, setValue } = useForm<FormData>();
    const [medicineList, setMedicineList] = useState<IItem[]>([])
    const [diseaseOption, setDiseaseOption] = useState<any[]>([]);
    const [diseaseSelected, setDiseaseSelected] = useState<any>();
    const [symptomOption, setSymptomOption] = useState<any[]>([]);
    const [symptomOptionFiltered, setSymptomOptionFiltered] = useState<any[]>([]);
    useEffect(() => {
        // onLoadItem();
        onLoadSymptom();
        onLoadDisease();
    }, [])


    const onLoadDisease = async () => {
        const res = await callApi.get('/disease?type=list');
        if (res.data?.data) {
            setDiseaseOption(res.data?.data)
        } else {
            Swal.fire('Error', res?.data.message, 'error')
        }
    }
    const onLoadSymptom = async () => {
        const res = await callApi.get('/symptom?type=list');
        if (res.data?.data) {
            setSymptomOption(res.data?.data)
            setSymptomOptionFiltered(res.data?.data)
        } else {
            Swal.fire('Error', res?.data.message, 'error')
        }
    }

    const handleFormSubmit = (data: FormData) => {
        console.log('submit data', data)
        if (data.symptom.length <= 0) {
            alert('โปรดระบุ Symptom')
            return;
        }
        if (data) {
            onSubmit(data);
            reset();
            onClose();
        }
    };

    const onSubmit = (data: FormData) => {

        var row = diseaseList;
        if (data) {
            const checkDub = row.find((item) => item.disease_group == data.disease_group)
            if (checkDub) {
                Swal.fire('Warning', data.disease_group + ' มีในรายการอยู่แล้ว', 'warning')
            } else {
                row.push({ ...data });
                setDiseaseList(row)
                console.log(JSON.stringify(row))
            }

        }

    };



    const handleDiseaseChange = async (value: any) => {
        if (value) {
            setDiseaseSelected(value);
            setValue('disease_group', value.id)
            setValue('disease_group_name', value.name)
            var newdata = symptomOption.filter(item => item.disease == value.id)
            setSymptomOptionFiltered(newdata);
            setValue('symptom', [])
        }
    }
    const handleSymptomChange = async (value: ISymptom[]) => {
        setValue('symptom', value)
    }


    return (
        <Dialog open={open} onClose={onClose}>
            <DialogTitle>บันทึกการรักษา (Treatment Record)</DialogTitle>
            <DialogContent>
                <form onSubmit={handleSubmit(handleFormSubmit)}>
                    <Autocomplete
                        {...register('disease_group')}
                        fullWidth
                        options={diseaseOption}
                        getOptionLabel={(option) => option.id + ' | ' + option.name}
                        onChange={(_, value) => handleDiseaseChange(value)}
                        renderInput={(params) => (
                            <TextField {...params} label="Disease" margin="normal" fullWidth required
                                // onBlur={handleChange} 
                                name='disease' />
                        )}
                    />
                    <Autocomplete
                        {...register('symptom')}
                        fullWidth
                        options={symptomOptionFiltered}
                        getOptionLabel={(option) => option.id + ' | ' + option.name}
                        onChange={(_, value) => handleSymptomChange(value)}
                        multiple
                        renderInput={(params) => (
                            <TextField {...params} label="Symptom" margin="normal" fullWidth
                                // onBlur={handleChange} 
                                name='Symptom' />
                        )}
                    />
                    <TextField
                        {...register('symptom_other')}
                        label="Simptom Other"
                        type="text"
                        fullWidth
                        margin="normal"
                        defaultValue={''}
                    />
                    <DialogActions>
                        <Button onClick={onClose}>ยกเลิก</Button>
                        <Button type="submit" variant="contained" color="primary">
                            บันทึก
                        </Button>
                    </DialogActions>
                </form>
            </DialogContent>
        </Dialog>
    );
};

export default DiseaseModal;
